void xlang_lsp_free_loaded_imports_impl(void **all_dep_mods, char **all_dep_paths, int n_all) {
    int i;

    for (i = 0; i < n_all; i++) {
        if (all_dep_paths[i]) {
            free(all_dep_paths[i]);
            all_dep_paths[i] = NULL;
        }
        if (all_dep_mods[i]) {
            ast_module_free(all_dep_mods[i]);
            all_dep_mods[i] = NULL;
        }
    }
}

