    int32_t esz_res;
    if (pipeline_type_kind_ord_at(arena, tr) == 10) {
      int32_t asz = glue_fixed_array_total_bytes_c(arena, tr, 0);
      if (asz > 0)
        return asz;
    }
    if (pipeline_type_kind_ord_at(arena, tr) == 9)
      return 8;
    if (pipeline_type_kind_ord_at(arena, tr) == 11)
      return 16;
