static int32_t win_pipeline_token_kind_variant_tag(const uint8_t *variant_name, int32_t variant_len) {
  static const char *const names[] = {
      "TOKEN_EOF",       "TOKEN_FUNCTION",  "TOKEN_LET",         "TOKEN_CONST",      "TOKEN_IF",
      "TOKEN_ELSE",      "TOKEN_WHILE",     "TOKEN_LOOP",        "TOKEN_FOR",        "TOKEN_BREAK",
      "TOKEN_CONTINUE",  "TOKEN_RETURN",    "TOKEN_PANIC",       "TOKEN_DEFER",      "TOKEN_MATCH",
      "TOKEN_STRUCT",    "TOKEN_PACKED",    "TOKEN_ENUM",        "TOKEN_GOTO",       "TOKEN_TRAIT",
      "TOKEN_IMPL",      "TOKEN_SELF",      "TOKEN_UNDERSCORE",  "TOKEN_IMPORT",     "TOKEN_EXTERN",
      "TOKEN_IDENT",     "TOKEN_I32",       "TOKEN_BOOL",        "TOKEN_U8",         "TOKEN_U32",
      "TOKEN_U64",       "TOKEN_I64",       "TOKEN_USIZE",       "TOKEN_ISIZE",      "TOKEN_I32X4",
      "TOKEN_I32X8",     "TOKEN_I32X16",    "TOKEN_U32X4",       "TOKEN_U32X8",      "TOKEN_U32X16",
      "TOKEN_F32X4",     "TOKEN_TRUE",      "TOKEN_FALSE",       "TOKEN_F32",        "TOKEN_F64",        "TOKEN_VOID",
      "TOKEN_INT",       "TOKEN_FLOAT",     "TOKEN_LPAREN",      "TOKEN_RPAREN",     "TOKEN_LBRACE",
      "TOKEN_RBRACE",    "TOKEN_LBRACKET",  "TOKEN_RBRACKET",    "TOKEN_ARROW",      "TOKEN_FATARROW",
      "TOKEN_COMMA",     "TOKEN_COLON",     "TOKEN_DOT",         "TOKEN_SEMICOLON",  "TOKEN_PLUS",
      "TOKEN_MINUS",     "TOKEN_STAR",      "TOKEN_SLASH",       "TOKEN_PERCENT",    "TOKEN_AMP",
      "TOKEN_PIPE",      "TOKEN_CARET",     "TOKEN_LSHIFT",      "TOKEN_RSHIFT",     "TOKEN_PLUS_EQ",
      "TOKEN_MINUS_EQ",  "TOKEN_STAR_EQ",   "TOKEN_SLASH_EQ",    "TOKEN_PERCENT_EQ", "TOKEN_AMP_EQ",
      "TOKEN_PIPE_EQ",   "TOKEN_CARET_EQ",  "TOKEN_LSHIFT_EQ",   "TOKEN_RSHIFT_EQ",  "TOKEN_TILDE",
      "TOKEN_ASSIGN",    "TOKEN_EQ",        "TOKEN_NE",          "TOKEN_LT",         "TOKEN_GT",
      "TOKEN_LE",        "TOKEN_GE",        "TOKEN_AMPAMP",      "TOKEN_PIPEPIPE",   "TOKEN_BANG",
      "TOKEN_QUESTION",  "TOKEN_AS",        "TOKEN_AT",
  };
  int32_t i;
  int32_t nlen;
  if (!variant_name || variant_len <= 0)
    return -1;
  for (i = 0; i < (int32_t)(sizeof(names) / sizeof(names[0])); i++) {
    nlen = (int32_t)strlen(names[i]);
    if (nlen == variant_len && memcmp(variant_name, names[i], (size_t)variant_len) == 0)
      return i;
  }
  return -1;
}

static int32_t win_pipeline_asm_typekind_variant_tag(const uint8_t *field_buf, int32_t flen) {
  if (!field_buf || flen < 7)
    return -1;
  if (flen >= 7 && memcmp(field_buf, "TYPE_I32", 7) == 0)
    return 0;
  if (flen >= 8 && memcmp(field_buf, "TYPE_BOOL", 8) == 0)
    return 1;
  if (flen >= 6 && memcmp(field_buf, "TYPE_U8", 6) == 0) {
    if (flen >= 9 && memcmp(field_buf, "TYPE_USIZE", 9) == 0)
      return 6;
    if (flen >= 7 && memcmp(field_buf, "TYPE_U32", 7) == 0)
      return 3;
    if (flen >= 7 && memcmp(field_buf, "TYPE_U64", 7) == 0)
      return 4;
    return 2;
  }
  if (flen >= 7 && memcmp(field_buf, "TYPE_U32", 7) == 0)
    return 3;
  if (flen >= 7 && memcmp(field_buf, "TYPE_U64", 7) == 0)
    return 4;
  if (flen >= 7 && memcmp(field_buf, "TYPE_I64", 7) == 0)
    return 5;
  if (flen >= 9 && memcmp(field_buf, "TYPE_USIZE", 9) == 0)
    return 6;
  if (flen >= 9 && memcmp(field_buf, "TYPE_ISIZE", 9) == 0)
    return 7;
  if (flen >= 9 && memcmp(field_buf, "TYPE_NAMED", 9) == 0)
    return 8;
  if (flen >= 7 && memcmp(field_buf, "TYPE_PTR", 7) == 0)
    return 9;
  if (flen >= 9 && memcmp(field_buf, "TYPE_ARRAY", 9) == 0)
    return 10;
  if (flen >= 9 && memcmp(field_buf, "TYPE_SLICE", 9) == 0)
    return 11;
  if (flen >= 11 && memcmp(field_buf, "TYPE_VECTOR", 11) == 0)
    return 12;
  if (flen >= 7 && memcmp(field_buf, "TYPE_F32", 7) == 0)
    return 13;
  if (flen >= 7 && memcmp(field_buf, "TYPE_F64", 7) == 0)
    return 14;
  if (flen >= 8 && memcmp(field_buf, "TYPE_VOID", 8) == 0)
    return 15;
  return -1;
}

static inline int32_t win_glue_slice_dual_gp_length_off_c(int32_t data_home, int32_t ta) {
  if (ta == 1)
    return data_home + 8;
  return data_home - 8;
}

static inline int32_t win_glue_field_access_effective_offset_c(void *arena, void *mod, int32_t fa_ref) {
  return pipeline_expr_field_access_layout_offset(arena, mod, fa_ref);
}

int32_t pipeline_asm_emit_var_field_access_elf_c(void *arena, void *elf_ctx, int32_t expr_ref, void *ctx, int32_t ta) {
  int32_t base_ref;
  int32_t vlen;
  int32_t var_off;
  int32_t field_off;
  int32_t load_sz;
  uint8_t vname[256];
  void *mod;

  base_ref = pipeline_expr_field_access_base_ref(arena, expr_ref);
  if (base_ref <= 0 || pipeline_expr_kind_ord_at(arena, base_ref) != 3)
    return -99;
  vlen = pipeline_expr_var_name_len(arena, base_ref);
  if (vlen <= 0 || vlen > 255)
    return -99;
  pipeline_expr_var_name_into(arena, base_ref, vname);
  var_off = asm_ctx_local_find_offset_scoped((uint8_t *)ctx, arena, vname, vlen);
  if (var_off < 0)
    var_off = asm_ctx_local_find_offset((uint8_t *)ctx, vname, vlen);
  if (var_off < 0)
    return -99;

  {
    int32_t base_ty_sl = glue_var_expr_type_ref_with_decl_fallback_c(arena, base_ref);
    int32_t flen_sl = pipeline_expr_field_access_name_len(arena, expr_ref);
    if (base_ty_sl > 0 && flen_sl > 0 && flen_sl <= 63 &&
        pipeline_type_kind_ord_at(arena, base_ty_sl) == 11 /* TYPE_SLICE */ &&
        glue_local_var_slot_needs_ptr_load_elf_c(arena, base_ref, var_off, ctx) == 0) {
      uint8_t fn_sl[256];
      pipeline_expr_field_access_name_into(arena, expr_ref, fn_sl);
      /* TYPE_SLICE local dual-GP `.length`: C fat MEMORY
       * {data@addr, length@addr+8}. leftover-PE named lets are
       * positive product offsets ([rbp-off]); x86 length half is
       * product home-8 (win_glue / leftover rest unique length_off).
       * Always var_off+8 was memory data-8: local `.length` of
       * CALL let-init GREEN at the wrong slot while ARRAY_LIT
       * store (SAT t home-8) RAN=56, and lea fat* as call-arg
       * SEGV. Formals (needs_ptr_load!=0) stay fat*+8 below.
       * PLATFORM: WINDOWS leftover-PE. */
      if (flen_sl == 6 && memcmp(fn_sl, "length", 6) == 0)
        return backend_enc_load_rbp_to_rax_arch(elf_ctx,
            win_glue_slice_dual_gp_length_off_c(var_off, ta), ta);
      if (flen_sl == 4 && memcmp(fn_sl, "data", 4) == 0)
        return backend_enc_load_rbp_to_rax_arch(elf_ctx, var_off, ta);
    }
  }

  mod = pipeline_asm_emit_module_ref_c();
  field_off = win_glue_field_access_effective_offset_c(arena, mod, expr_ref);
  if (glue_enc_local_slot_ptr_or_addr_elf_c(arena, elf_ctx, base_ref, var_off, ctx, ta) != 0)
    return -1;
  if (field_off != 0 && backend_enc_add_imm_to_rax_arch(elf_ctx, field_off, ta) != 0)
    return -1;

  /* TYPE_FN=18 / TYPE_PTR=9: pointer-sized. SAT load_byte_sz scans every
   * layout for field name `f` and can steal i32 width (cltq + call *trunc).
   * leftover rest WAVE278 resolved_type + WAVE270 kind, same .o.
   * dest-ARRAY does not stamp FA resolved (dest-SLICE stamps TYPE_SLICE).
   * SAT load_byte_sz → glue_field_access_load_bytes_for_type_ref TYPE_ARRAY
   * catch-all 4 (`arr_field_arg` rec 4B of a[0]=3, INTEGER home, INDEX1=0).
   * TYPE_ARRAY 8B leftover-PE payload load_64; >8B leave E*. Layout via
   * leftover rest unique win_glue_fa_layout_type_ref (same TU; emit_module
   * ref). Do not leftover rest T SAT load_byte_sz (SHARED i32 widths).
   * Do not leftover rest T SAT try_index (arr0).
   * PLATFORM: WINDOWS leftover-PE / SHARED Cap ABI. */
  {
    int32_t rtr = pipeline_expr_resolved_type_ref(arena, expr_ref);
    int32_t rko = (rtr > 0) ? pipeline_type_kind_ord_at(arena, rtr) : 0;
    int32_t fty;
    int32_t nbytes;
    if (rko == 9 || rko == 18)
      load_sz = 8;
    else if (rko == 11)
      /* TYPE_SLICE field: 16B fat dual-GP. SAT load_byte_sz was 4
       * (`mov (%rax),%eax` truncated dest; `take(s.xs)` SEGV).
       * rax holds &field; deref_struct16 loads C {data,length}.
       * PLATFORM: WINDOWS leftover-PE. */
      return pipeline_asm_deref_struct16_rax_ptr_elf_c(elf_ctx, ta);
    else {
      fty = 0;
      if (rko == 10)
        fty = rtr;
      if (fty <= 0)
        fty = win_glue_fa_layout_type_ref_c(arena, mod, ctx, expr_ref);
      if (fty > 0 && glue_type_is_fixed_array(arena, fty) != 0) {
        nbytes = glue_fixed_array_total_bytes_c(arena, fty, 0);
        if (nbytes > 0 && nbytes <= 8)
          return backend_enc_load_64_from_rax_arch(elf_ctx, ta);
        return 0;
      }
      load_sz = pipeline_expr_field_access_load_byte_sz(arena, mod, expr_ref);
    }
  }
  if (load_sz == 1)
    return backend_enc_load_zext8_from_rax_arch(elf_ctx, ta);
  if (load_sz == 8)
    return backend_enc_load_64_from_rax_arch(elf_ctx, ta);
  return backend_enc_load_32_from_rax_arch(elf_ctx, ta);
}

/**
 * EXPR_FIELD_ACCESS fast path: enum TokenKind/ExprKind/TypeKind, VAR fields.
 * PLATFORM: WINDOWS leftover-PE · SHARED freestanding emit.
 */
int32_t pipeline_asm_emit_field_access_elf_fast_c(void *arena, void *elf_ctx, int32_t expr_ref, void *ctx, int32_t ta) {
  int32_t fa_base2;
  int32_t blen2;
  void *mod;

  if (pipeline_expr_field_access_is_enum_variant(arena, expr_ref) != 0)
    return backend_enc_mov_imm32_to_w0_arch(elf_ctx, pipeline_expr_enum_variant_tag_at(arena, expr_ref), ta);

  {
    int32_t flen_arr = pipeline_expr_field_access_name_len(arena, expr_ref);
    if (flen_arr == 6) {
      uint8_t fn_arr[256];
      int32_t base_ref_arr;
      int32_t base_ty_arr;
      int32_t bk_arr;
      int32_t asz_arr;
      pipeline_expr_field_access_name_into(arena, expr_ref, fn_arr);
      if (memcmp(fn_arr, "length", 6) == 0) {
        base_ref_arr = pipeline_expr_field_access_base_ref(arena, expr_ref);
        base_ty_arr = glue_var_expr_type_ref_with_decl_fallback_c(arena, base_ref_arr);
        if (base_ty_arr <= 0)
          base_ty_arr = pipeline_expr_resolved_type_ref(arena, base_ref_arr);
        if (base_ty_arr > 0) {
          bk_arr = pipeline_type_kind_ord_at(arena, base_ty_arr);
          if (bk_arr == 10 /* TYPE_ARRAY */ || bk_arr == 13 /* TYPE_VECTOR */) {
            asz_arr = pipeline_type_array_size_at(arena, base_ty_arr);
            if (asz_arr > 0)
              return backend_enc_mov_imm64_to_rax_arch(elf_ctx, asz_arr, 0, ta);
          }
        }
      }
    }
  }

  fa_base2 = pipeline_expr_field_access_base_ref(arena, expr_ref);
  mod = pipeline_asm_emit_module_ref_c();

  /** SoA `arr[i].field` */
  if (fa_base2 > 0 && pipeline_expr_kind_ord_at(arena, fa_base2) == 47) {
    int32_t load_sz;
    if (pipeline_expr_field_access_soa_stride(arena, expr_ref) <= 0 && mod != 0) {
      (void)typeck_soa_field_soa_index(mod, arena, expr_ref, fa_base2);
    }
    if (pipeline_asm_emit_lvalue_eff_addr_elf_c(arena, elf_ctx, expr_ref, ctx, ta) != 0)
      return -99;
    load_sz = pipeline_expr_field_access_load_byte_sz(arena, mod, expr_ref);
    if (load_sz == 1)
      return backend_enc_load_zext8_from_rax_arch(elf_ctx, ta);
    if (load_sz == 8)
      return backend_enc_load_64_from_rax_arch(elf_ctx, ta);
    return backend_enc_load_i32_indirect_to_rax_arch(elf_ctx, ta);
  }

  /*
   * CALL/METHOD/STRUCT_LIT rvalue base, including nested FIELD chain
   * (`mk().x` / `mk().p.f` / `(P { x: 3, y: 4 }).x` /
   * `(Outer { p: Inner { f } }).p.f` / `(Outer { p: &i }).p.f`).
   * G.7 complete leftover rest WIN leftover field_access_fast: SAT
   * glue_field_access_call_base_rvalue is SAT local t — leftover rest UNDEF
   * does not resolve (ld -r keeps U; final gcc fails). Walk FIELD (ko==44)
   * to CALL(48)/METHOD(49)/STRUCT_LIT(45) root (SAT wave593 walk; cap 16).
   * Materialise root once:
   *   STRUCT_LIT: SAT emit_struct_lit global T; dest pointer stays in rbx
   *   CALL/METHOD: leftover rest rec (SAT emit_call global T) then layout
   *     temp (LP64 next_offset@4; x86 high-end home=off+alloc):
   *       ≤8B packed rax store; 9–16B dual-GP rax@home + rdx@home-8;
   *       >16B SysV sret (lea dest, rdi=arg0, sret_reg_shift=1)
   * then add each field offset inner→outer; intermediate hops (ci>0) whose
   * WAVE278 resolved_type_ref is TYPE_PTR=9 load *T (SAT wave596) so outer
   * offsets apply through the pointer. Never peel TYPE_SLICE=11 (by-value
   * fat; SAT glue_field_chain_mid_auto_deref is *T only).
   * SAT glue_index_deref_ptr_field_slot_rax leftover rest FROM_X T is a
   * no-op stub (rest-first would win); glue_field_access_field_type_ref
   * leftover rest T returns 0 — do not UNDEF either. Use WAVE278
   * resolved_type_ref + WAVE270 type_kind_ord + backend_enc_load_64.
   * SAT glue_align_next_offset / glue_store_retval are leftover rest FROM_X
   * ABSENT (SAT store_retval remaining-wave is a stub / local t) — bump
   * next_offset inline; store rax/rdx via backend_enc (global T). SAT
   * set_call_sret_reg_shift / set_call_expected_ret_ty are SAT global T
   * (dispatch UNDEF getter). Do not UNDEF SAT glue_field_access_call_base
   * (SAT local t).
   * Prior: CALL.field offset≥8 of 12/16B RUN=0; >16B CALL.field sret
   * RUN=184/0. let-bind `let p = mk()` already green (SAT let_init).
   * PIPELINE_ASM_ELF_EXPR_FAST_UNHANDLED=-99.
   * PLATFORM: WINDOWS leftover-PE · SHARED freestanding emit.
   */
  {
    int32_t chain_fa[16];
    int32_t chain_n;
    int32_t cur_fa;
    int32_t root_ref;
    int32_t root_ko;
    int32_t chain_depth;
    chain_n = 0;
    cur_fa = expr_ref;
    root_ref = 0;
    root_ko = 0;
    chain_depth = 0;
    while (chain_depth < 16 && chain_n < 16) {
      int32_t next_base;
      int32_t nko;
      chain_fa[chain_n++] = cur_fa;
      next_base = pipeline_expr_field_access_base_ref(arena, cur_fa);
      if (next_base <= 0)
        break;
      nko = pipeline_expr_kind_ord_at(arena, next_base);
      if (nko == 48 || nko == 49 || nko == 45) {
        root_ref = next_base;
        root_ko = nko;
        break;
      }
      if (nko == 44) {
        cur_fa = next_base;
        chain_depth++;
        continue;
      }
      break;
    }
    if (root_ref > 0 && (root_ko == 45 || root_ko == 48 || root_ko == 49)) {
      int32_t rc;
      int32_t load_sz;
      int32_t ci;
      if (root_ko == 45) {
        rc = pipeline_asm_emit_struct_lit_elf_c(arena, elf_ctx, root_ref, ctx, ta);
        if (rc != 0)
          return rc;
        if (backend_enc_mov_rbx_to_rax_arch(elf_ctx, ta) != 0)
          return -1;
      } else {
        int32_t *ly_next;
        int32_t off;
        int32_t m;
        int32_t home;
        int32_t ret_sz;
        int32_t alloc_sz;
        int32_t root_ty;
        if (!ctx)
          return -1;
        ly_next = (int32_t *)((uint8_t *)ctx + 4); /* LP64 AsmFuncCtx.next_offset@4 */
        off = *ly_next;
        m = off % 8;
        if (m != 0)
          off = off + (8 - m);
        root_ty = pipeline_expr_resolved_type_ref(arena, root_ref);
        ret_sz = 0;
        if (root_ty > 0)
          ret_sz = glue_type_size_simple(mod, arena, root_ty, 0);
        if (ret_sz <= 0)
          ret_sz = glue_call_return_byte_size_c(arena, root_ref);
        if (ret_sz <= 0)
          ret_sz = 8;
        if (ret_sz > 4096)
          return -99;
        if (ret_sz <= 8)
          alloc_sz = 8;
        else if (ret_sz <= 16)
          alloc_sz = 16;
        else
          alloc_sz = (ret_sz + 7) & ~7;
        /* PLATFORM: WINDOWS leftover-PE x86_64 SysV — high-end home=off+alloc.
         * dual-GP: low@home (rax), high@home-8 (rdx). sret byte0@home.
         * SAT call_base_rvalue ta!=1 matches this (arm64 ta==1 is not leftover-PE). */
        home = off + alloc_sz;
        *ly_next = home;
        if (ret_sz > 16) {
          pipeline_asm_set_call_expected_ret_ty_c(root_ty > 0 ? root_ty : 0);
          if (backend_enc_lea_rbp_to_rax_arch(elf_ctx, home, ta) != 0) {
            pipeline_asm_set_call_expected_ret_ty_c(0);
            return -1;
          }
          if (backend_enc_mov_rax_to_arg_reg_arch(elf_ctx, 0, ta) != 0) {
            pipeline_asm_set_call_expected_ret_ty_c(0);
            return -1;
          }
          pipeline_asm_emit_set_call_sret_reg_shift_c(1);
          rc = pipeline_asm_emit_expr_elf_rec(arena, elf_ctx, root_ref, ctx, ta);
          pipeline_asm_emit_set_call_sret_reg_shift_c(0);
          pipeline_asm_set_call_expected_ret_ty_c(0);
          if (rc != 0)
            return rc;
        } else {
          rc = pipeline_asm_emit_expr_elf_rec(arena, elf_ctx, root_ref, ctx, ta);
          if (rc != 0)
            return rc;
          if (backend_enc_store_rax_to_rbp_arch(elf_ctx, home, ta) != 0)
            return -1;
          if (ret_sz > 8) {
            if (backend_enc_store_rdx_to_rbp_arch(elf_ctx, home - 8, ta) != 0)
              return -1;
          }
        }
        if (backend_enc_lea_rbp_to_rax_arch(elf_ctx, home, ta) != 0)
          return -1;
      }
      for (ci = chain_n - 1; ci >= 0; ci--) {
        int32_t fo = pipeline_expr_field_access_layout_offset(arena, mod, chain_fa[ci]);
        int32_t mid_tr;
        int32_t mid_k;
        if (fo != 0 && backend_enc_add_imm_to_rax_arch(elf_ctx, fo, ta) != 0)
          return -1;
        /* Intermediate hop: *T auto-deref (SAT wave596). Never peel SLICE. */
        if (ci > 0) {
          mid_tr = pipeline_expr_resolved_type_ref(arena, chain_fa[ci]);
          mid_k = (mid_tr > 0) ? pipeline_type_kind_ord_at(arena, mid_tr) : 0;
          if (mid_k == 9 /* TYPE_PTR */ &&
              backend_enc_load_64_from_rax_arch(elf_ctx, ta) != 0)
            return -1;
        }
      }
      {
        int32_t rtr = pipeline_expr_resolved_type_ref(arena, expr_ref);
        int32_t rko = (rtr > 0) ? pipeline_type_kind_ord_at(arena, rtr) : 0;
        if (rko == 9 || rko == 18)
          load_sz = 8;
        else if (rko == 11)
          return pipeline_asm_deref_struct16_rax_ptr_elf_c(elf_ctx, ta);
        else
          load_sz = pipeline_expr_field_access_load_byte_sz(arena, mod, expr_ref);
      }
      if (load_sz == 1)
        return backend_enc_load_zext8_from_rax_arch(elf_ctx, ta);
      if (load_sz == 8)
        return backend_enc_load_64_from_rax_arch(elf_ctx, ta);
      return backend_enc_load_32_from_rax_arch(elf_ctx, ta);
    }
  }

  /** VAR field access */
  if (fa_base2 > 0 && pipeline_expr_kind_ord_at(arena, fa_base2) == 3) {
    blen2 = pipeline_expr_var_name_len(arena, fa_base2);
    if (blen2 >= 9) {
      uint8_t bn[256];
      uint8_t fb[256];
      int32_t flen2 = pipeline_expr_field_access_name_len(arena, expr_ref);
      int32_t tk;
      pipeline_expr_var_name_into(arena, fa_base2, bn);
      if (memcmp(bn, "TokenKind", 9) == 0 && flen2 > 0) {
        pipeline_expr_field_access_name_into(arena, expr_ref, fb);
        tk = win_pipeline_token_kind_variant_tag(fb, flen2);
        if (tk < 0) {
          int32_t sl = (int32_t)strlen((const char *)fb);
          if (sl > 0 && sl < flen2)
            tk = win_pipeline_token_kind_variant_tag(fb, sl);
        }
        if (tk >= 0)
          return backend_enc_mov_imm32_to_w0_arch(elf_ctx, tk, ta);
      }
    }
    if (blen2 >= 8) {
      uint8_t bn[256];
      uint8_t fb[256];
      int32_t flen2 = pipeline_expr_field_access_name_len(arena, expr_ref);
      int32_t ev_tag;
      pipeline_expr_var_name_into(arena, fa_base2, bn);
      if (memcmp(bn, "TypeKind", 8) == 0 && flen2 > 0) {
        pipeline_expr_field_access_name_into(arena, expr_ref, fb);
        ev_tag = win_pipeline_asm_typekind_variant_tag(fb, flen2);
        if (ev_tag >= 0)
          return backend_enc_mov_imm32_to_w0_arch(elf_ctx, ev_tag, ta);
      }
      if (memcmp(bn, "ExprKind", 8) == 0 && flen2 > 0) {
        ev_tag = pipeline_expr_enum_namespace_field_tag(arena, expr_ref);
        if (ev_tag >= 0)
          return backend_enc_mov_imm32_to_w0_arch(elf_ctx, ev_tag, ta);
      }
    }
    {
      int32_t vr = pipeline_asm_emit_var_field_access_elf_c(arena, elf_ctx, expr_ref, ctx, ta);
      if (vr != -99)
        return vr;
    }
  }

  {
    int32_t ns_tag = pipeline_expr_enum_namespace_field_tag(arena, expr_ref);
    if (ns_tag >= 0)
      return backend_enc_mov_imm32_to_w0_arch(elf_ctx, ns_tag, ta);
  }

  /** Chained / general FIELD_ACCESS: lvalue eff addr + load */
  {
    int32_t load_sz;
    if (pipeline_asm_emit_lvalue_eff_addr_elf_c(arena, elf_ctx, expr_ref, ctx, ta) != 0)
      return -99;
    {
      int32_t rtr = pipeline_expr_resolved_type_ref(arena, expr_ref);
      int32_t rko = (rtr > 0) ? pipeline_type_kind_ord_at(arena, rtr) : 0;
      if (rko == 9 || rko == 18)
        load_sz = 8;
      else if (rko == 11)
        return pipeline_asm_deref_struct16_rax_ptr_elf_c(elf_ctx, ta);
      else
        load_sz = pipeline_expr_field_access_load_byte_sz(arena, mod, expr_ref);
    }
    if (load_sz == 1)
      return backend_enc_load_zext8_from_rax_arch(elf_ctx, ta);
    if (load_sz == 8)
      return backend_enc_load_64_from_rax_arch(elf_ctx, ta);
    return backend_enc_load_32_from_rax_arch(elf_ctx, ta);
  }
}
