static inline int32_t win_return_load_i32(const void *p, int32_t off) {
  const uint8_t *b = (const uint8_t *)p + off;
  return (int32_t)((uint32_t)b[0] | ((uint32_t)b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24));
}

/**
 * Windows leftover-PE hybrid return_impl (wave144 cold face).
 * TYPE_ARRAY `return a` of a local [N]T: SAT remaining-wave Path B0 is
 * `#ifndef FROM_X` ABSENT; emit_expr of VAR load_var payload then the
 * caller treats rax as E* (`arr_ret_whole` SEGV 139). G.7 complete
 * leftover rest unique emit_return (already first-wins T): POSIX Path B0
 * durable COMMON via leftover rest unique helper. ARRAY_LIT stays
 * mega_body durable. Do not leftover rest remaining-wave emit_return
 * via !FROM_X || WIN.
 * PLATFORM: WINDOWS leftover-PE hybrid; POSIX FROM_X path remains unchanged.
 */
int32_t pipeline_asm_emit_return_elf_impl(void *arena, void *elf_ctx, int32_t expr_ref,
                                          void *ctx, int32_t ta) {
  uint8_t *ly;
  int32_t ret_op;
  int32_t tj_len;
  int32_t ti;
  uint8_t tj_lbl[128];
  int32_t ret_rty;
  int32_t ret_rtk;
  int32_t ret_fi;
  void *ret_mod;
  int32_t ret_st;

  ly = (uint8_t *)pipeline_asm_ctx_layout(ctx);
  ret_op = pipeline_expr_unary_operand_ref_at(arena, expr_ref);
  if (ret_op != 0) {
    ret_st = -2;
    ret_rty = 0;
    ret_rtk = 0;
    ret_mod = pipeline_asm_emit_module_ref_c();
    ret_fi = pipeline_asm_emit_func_index_c();
    if (ret_mod && ret_fi >= 0)
      ret_rty = pipeline_module_func_return_type_at(ret_mod, ret_fi);
    if (ret_rty <= 0)
      ret_rty = pipeline_expr_resolved_type_ref(arena, ret_op);
    if (ret_rty > 0)
      ret_rtk = pipeline_type_kind_ord_at(arena, ret_rty);
    if (ret_rty > 0 && ret_rtk == 10)
      ret_st = glue_emit_fixed_array_return_durable_ptr_rax_elf_c(arena, elf_ctx, ret_op, ctx, ta,
                                                                 ret_rty);
    if (ret_st == -1)
      return -1;
    if (ret_st != 0) {
      if (pipeline_asm_emit_expr_elf_c(arena, elf_ctx, ret_op, ctx, ta) != 0)
        return -1;
    }
  }
  if (glue_index_scratch_spills_cleanup_all_elf_c(elf_ctx, ta) != 0)
    return -1;
  if (glue_async_cps_emit_phase_reset(elf_ctx, ta) != 0)
    return -1;
  if (!ly)
    return -1;
  tj_len = win_return_load_i32(ly, 1520 /* W144_LY_TAIL_JOIN_LEN */);
  if (tj_len <= 0)
    return -1;
  for (ti = 0; ti < tj_len && ti < 128; ti++)
    tj_lbl[ti] = ly[1392 /* W144_LY_TAIL_JOIN_LBL */ + ti];
  return backend_enc_jmp_arch(elf_ctx, tj_lbl, tj_len, ta);
}

/**
 * Windows leftover-PE: get_return expr_stmts fallback must return RETURN operand.
 * Seed #ifndef FROM_X twin is excluded from FROM_X rest; standalone/.x amalgam
 * still has historical `return 0` on EXPR_RETURN which yields empty .text when
 * stmt_order is 0. Rest links before thin → same-TU mega binds here.
 * Reads W277_Block fields via arena pointer (avoid ast_ast_block_* PE stubs).
 * PLATFORM: WINDOWS leftover-PE hybrid.
 */
extern int32_t pipeline_block_num_labeled_stmts(void *a, int32_t body_ref);
extern int32_t pipeline_block_labeled_return_expr_ref(void *a, int32_t body_ref, int32_t j);
extern int32_t pipeline_block_expr_stmt_ref(void *a, int32_t body_ref, int32_t ei);
extern int32_t pipeline_expr_kind_ord_at(void *a, int32_t expr_ref);
extern int32_t pipeline_expr_unary_operand_ref_at(void *a, int32_t expr_ref);
