  if (!ex)
    return 0;
  memcpy(&kind, ex + 0, 4);
  if (kind == 1) {
    memcpy(&fv, ex + 24, 8);
    return (int32_t)typeck_float64_bits_hi(fv);
  }
  memcpy(&hi, ex + 688, 4);
  return hi;
